def find_hollow_shapes_only(grid):
    """Keep only shapes that are hollow rectangles/squares"""
    result = [[3]*len(grid[0]) for _ in range(len(grid))]

    # Find all hollow rectangular shapes
    def expand_right(r, c, color):
        while c < len(grid[0]) - 1 and grid[r][c+1] == color:
            c += 1
        return c

    def expand_down(r, c, color):
        while r < len(grid) - 1 and grid[r+1][c] == color:
            r += 1
        return r

    def is_hollow_rectangle(start_r, start_c, end_r, end_c):
        # Check border is complete
        top_ok = all(grid[start_r][j] == grid[start_r][start_c] 
                     for j in range(start_c, end_c+1))
        bottom_ok = all(grid[end_r][j] == grid[end_r][end_c] 
                        for j in range(start_c, end_c+1))
        left_ok = all(grid[i][start_c] == grid[end_r][end_c] 
                      for i in range(start_r, end_r+1))
        right_ok = all(grid[i][end_c] == grid[end_r][end_c] 
                       for i in range(start_r, end_r+1))

        if not (top_ok and bottom_ok and left_ok and right_ok):
            return False

        # Check interior has background or other colors
        interior_cells = []
        for i in range(start_r+1, end_r):
            for j in range(start_c+1, end_c):
                interior_cells.append((i, j, grid[i][j]))
        return True  # Interior can be anything except all same as border

    visited = [[False]*len(grid[0]) for _ in range(len(grid))]
    found_shapes = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 3 and not visited[r][c]:
                color = grid[r][c]
                queue = deque([(r, c)])
                visited[r][c] = True
                shape_pixels = [(r, c)]

                while queue:
                    cr, cc = queue.popleft()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                shape_pixels.append((nr, nc))
                                queue.append((nr, nc))

                # Find bounding box
                min_r, max_r = min(p[0] for p in shape_pixels), max(p[0] for p in shape_pixels)
                min_c, max_c = min(p[1] for p in shape_pixels), max(p[1] for p in shape_pixels)

                # Check if it's a rectangle where corners exist but interior has different colors
                if grid[min_r][min_c] == color and grid[min_r][max_c] == color:
                    if grid[max_r][min_c] == color and grid[max_r][max_c] == color:
                        # Has four corners of correct color
                        # Check if interior exists (hollow)
                        if max_r > min_r + 1 and max_c > min_c + 1:
                            # Verify interior isn't solid
                            all_same_as_border = True
                            for i in range(min_r+1, max_r):
                                for j in range(min_c+1, max_c):
                                    if grid[i][j] != 3:  # If any interior cell has content
                                        all_same_as_border = False
                                        break
                                if not all_same_as_border:
                                    break

                            if not all_same_as_border:
                                # This is a hollow shape
                                for pr, pc in shape_pixels:
                                    result[pr][pc] = color
                                found_shapes.append({'color': color, 'bbox': (min_r, min_c, max_r, max_c)})

                                # Mark interior cells as visited so we don't process them separately
                                for i in range(min_r+1, max_r):
                                    for j in range(min_c+1, max_c):
                                        if grid[i][j] == 3:
                                            visited[i][j] = True

    return result, found_shapes

hollow_grid, hollow_shapes = find_hollow_shapes_only(grid)
print("Found hollow shapes:")
